package com.magraoxx.eichattv;
import android.Manifest;import android.app.Activity;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 private static final int REQ_MIC=1001;private TextView status,caption,micText;private Button listen,account;private TextToSpeech tts;private CommandEngine engine;private OpenAiClient ai;private ChatGptAuth auth;private AiVoiceRecorder recorder;private boolean pending;
 public void onCreate(Bundle b){super.onCreate(b);engine=new CommandEngine(this);ai=new OpenAiClient(this);auth=new ChatGptAuth(this);recorder=new AiVoiceRecorder(this);buildUi();refreshAccount();tts=new TextToSpeech(this,x->{if(x==0){tts.setLanguage(new Locale("pt","BR"));tts.setSpeechRate(1.02f);}});if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);if(getIntent()!=null&&getIntent().getBooleanExtra("start_listening",false))startListening();}
 private TextView text(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);return v;}private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}private Button button(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(17);b.setTextColor(Color.BLACK);b.setFocusable(true);b.setOnClickListener(l);return b;}
 private void buildUi(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(12,14,18));LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setGravity(Gravity.CENTER);center.setPadding(70,42,70,42);root.addView(center,new FrameLayout.LayoutParams(-1,-1));TextView logo=text("Ei Chat",42);logo.setGravity(Gravity.CENTER);logo.setTypeface(null,1);center.addView(logo,new LinearLayout.LayoutParams(-1,-2));caption=text("Assistente com IA",19);caption.setGravity(Gravity.CENTER);caption.setTextColor(Color.LTGRAY);center.addView(caption);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(38,26,38,26);card.setBackground(bg(Color.rgb(30,33,40),30));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,32,0,16);center.addView(card,cp);status=text("Conecte sua conta ChatGPT para começar",25);status.setGravity(Gravity.CENTER);card.addView(status);micText=text("● aguardando conexão",16);micText.setGravity(Gravity.CENTER);micText.setPadding(0,15,0,4);card.addView(micText);account=button("Conectar conta ChatGPT",v->connectChatGpt());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(430,68);ap.gravity=Gravity.CENTER;ap.setMargins(0,16,0,8);center.addView(account,ap);listen=button("🎤  OUVIR COM IA",v->startListening());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(430,68);bp.gravity=Gravity.CENTER;center.addView(listen,bp);Button diag=button("Diagnóstico",v->{caption.setText("Diagnóstico");status.setText(TvMicrophone.report(this)+"\nChatGPT: "+auth.accountLabel());});LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(430,58);dp.gravity=Gravity.CENTER;dp.setMargins(0,8,0,0);center.addView(diag,dp);setContentView(root);}
 private void refreshAccount(){boolean ok=auth.isConnected();account.setText(ok?"ChatGPT conectado: "+auth.accountLabel():"Conectar conta ChatGPT");listen.setEnabled(ok);if(ok){caption.setText("Assistente com IA");status.setText("Pressione OUVIR COM IA e fale normalmente");micText.setText("● IA pronta");}else{status.setText("Conecte sua conta ChatGPT para usar a IA");micText.setText("● aguardando conexão");}}
 private void connectChatGpt(){caption.setText("Ei Chat • conexão");status.setText("Abrindo login do ChatGPT…\nConclua a autorização no navegador e volte ao Ei Chat.");account.setEnabled(false);auth.signIn(new ChatGptAuth.Callback(){public void onSuccess(String m){runOnUiThread(()->{account.setEnabled(true);refreshAccount();status.setText(m+"\nAgora a IA está pronta para o teste.");});}public void onError(String e){runOnUiThread(()->{account.setEnabled(true);caption.setText("Ei Chat");status.setText(e);micText.setText("● conexão necessária");});}});}
 private void startListening(){if(!auth.isConnected()){connectChatGpt();return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pending=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);return;}caption.setText("Ei Chat • ouvindo");status.setText("Pode falar…");micText.setText(TvMicrophone.findBuiltIn(this)!=null?"● capturando microfone interno para IA":"● capturando áudio para IA");recorder.record(new AiVoiceRecorder.Callback(){public void onRecorded(java.io.File wav,String route){runOnUiThread(()->{caption.setText("Ei Chat • transcrevendo com IA");status.setText("Entendendo sua voz…");micText.setText("● "+route);});ai.transcribe(wav,new OpenAiClient.Callback(){public void onSuccess(String q){runOnUiThread(()->handle(q));}public void onError(String e){runOnUiThread(()->{caption.setText("Ei Chat • erro da IA");status.setText(e);micText.setText("● toque em Conectar conta se a sessão expirou");});}});}public void onError(String e){runOnUiThread(()->status.setText("Microfone: "+e));}});}
 private void handle(String q){caption.setText("Você disse");status.setText("“"+q+"”");CommandEngine.Result r=engine.execute(q);if(r.handled){caption.setText("Ei Chat");status.setText(r.message);if(!r.success)speak(r.message);return;}caption.setText("Ei Chat • pensando com IA");status.setText("Pensando…");ai.ask(q,new OpenAiClient.Callback(){public void onSuccess(String x){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(x);speak(x);});}public void onError(String x){runOnUiThread(()->{caption.setText("Ei Chat • erro da IA");status.setText(x);});}});}
 private void speak(String x){if(tts!=null&&x!=null&&!x.trim().isEmpty())tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"ei_chat");}
 public void onRequestPermissionsResult(int c,String[] p,int[] g){super.onRequestPermissionsResult(c,p,g);if(c==REQ_MIC&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&pending){pending=false;startListening();}}protected void onResume(){super.onResume();if(auth!=null)refreshAccount();}protected void onDestroy(){recorder.stop();if(tts!=null)tts.shutdown();super.onDestroy();}
}
